// Registry is what a check asks: a tag's digest, and a repository's tags. It is
// a pair of functions so the policy can be tested without a network.
type Registry struct {
	Digest func(ref remediation.Ref, tag string) (string, error)
	Tags   func(ref remediation.Ref) ([]string, error)
}

// Default reaches each image's own registry, with the credentials the engine
// holds for it or anonymously.
func Default() Registry {
	creds := func(ref remediation.Ref) (string, string) {
		host := ref.Registry
		if host == "" {
			host = "docker.io"
		}
		user, pass, _ := docker.GetStoredCreds(host)
		return user, pass
	}
	return Registry{
		Digest: func(ref remediation.Ref, tag string) (string, error) {
			user, pass := creds(ref)
			return oci.ManifestDigest(oci.RegistryAPIBase(ref.Registry), ref.Repository, tag, user, pass)
		},
		Tags: func(ref remediation.Ref) ([]string, error) {
			user, pass := creds(ref)
			return oci.ListRegistryTags(oci.RegistryAPIBase(ref.Registry), ref.Repository, user, pass)
		},
	}
}

// Check returns the facts for each reference: from the cache while they are
// fresh, from the registry otherwise, and stores what it fetched. It never
// fails: a registry that does not answer is that reference's Failed.
//
// It does I/O and belongs in a Cmd.
func Check(reg Registry, refs []string, now time.Time) map[string]Facts {

// ManifestDigest returns the digest a tag currently points to, from the
// registry's Docker-Content-Digest header.
//
// It is a HEAD request: Docker Hub does not count a HEAD against the pull rate
// limit, and nothing but the header is needed.
func ManifestDigest(apiURL, repo, tag, username, password string) (string, error) {
	rawURL := fmt.Sprintf("%s/v2/%s/manifests/%s", strings.TrimSuffix(apiURL, "/"), repo, url.PathEscape(tag))
	resp, _, err := registryDo(http.MethodHead, rawURL, manifestAccept, username, password, "")
	if err != nil {
		return "", err
	}
	_ = resp.Body.Close()
	if resp.StatusCode != http.StatusOK {
		return "", fmt.Errorf("registry returned %d for %s:%s", resp.StatusCode, repo, tag)
	}
	digest := resp.Header.Get("Docker-Content-Digest")
	if digest == "" {
		return "", fmt.Errorf("registry gave no digest for %s:%s", repo, tag)
	}
	return digest, nil
}

// RegistryAPIBase is the v2 API root of a registry named in an image reference:
// Docker Hub has its own host, a local registry is reached over plain HTTP, and
// everything else over HTTPS. An empty registry is Docker Hub.
func RegistryAPIBase(registry string) string {
//
// It reuses the pull the registry browser already emits, so a pull started by
// an agent is the same run, the same spinner in the Images table and the same
// entry in `:jobs` as one started by a key (§3.60).
func (m Model) handleImagePullRequested(msg ImagePullRequestedMsg) (tea.Model, tea.Cmd) {
	if msg.Image == "" {
		return m, jobs.Refuse(msg.Invocation, "No image named")
	}
	// A pull names an image that is on a registry, not one this view lists, so
	// it does not wait for the listing the way a scan does.
	if m.pullingImage(msg.Image) {
		return m, jobs.Refuse(msg.Invocation, "This image is already being pulled")
	}

	return m, jobs.WithInvocation(msg.Invocation,
		jobs.Start(m.pullRun(msg.Image), pullOneImageCmd(msg.Image)))
}

