194	// readKey loads a key file when the policy is read, not when an image is
195	// verified: an unreadable key rejects the file at once, the way a typo does,
196	// and the key's content — not its path — is what the cache fingerprint covers.
197	// A KMS URI is left for cosign to resolve.
198	func readKey(ref, dir string) (Key, error) {
199		if strings.Contains(ref, "://") {
200			return Key{Ref: ref}, nil
201		}
202		path := ref
203		if rest, ok := strings.CutPrefix(path, "~/"); ok {
204			home, err := os.UserHomeDir()
205			if err != nil {
