}

func appendIdentity(ids []trust.Identity, id trust.Identity) []trust.Identity {
	if id.Subject == "" || id.Issuer == "" {
		return ids
	}
	for _, have := range ids {
		if have == id {
			return ids
		}
	}
	return append(ids, id)
}

